  _ = `شكرًا على المشاركة في %1$s!`,
  _ = `سيساعدنا هذا الاستبيان السريع على فهم تجربتك في هذا الحدث ومساعدتنا في تحسين طريقة تنظيمنا للأحداث المستقبلية على Steam.`,
