  _ = `النسخة "%1$s" متاحة الآن للاعبين في الفرع "%2$s"`,
  _ = `الآن، أخبر اللاعبين عن تغييراتك`,
  _ = `سيظهر للاعبين الذين ثبّتوا لعبتك أن تحديثًا في قائمة الانتظار للتنزيل. من المرجح أنهم سيرغبون في معرفة ما الذي تغيّر.`,
  _ = `استخدم النموذج الموجود على اليمين للنشر كتحديث صغير أو افتح المحرر الكامل لنشر ملاحظات التغييرات كتحديث عادي أو رئيسي.`,
