  _ = `كما ستُنشر ملاحظات برنامج التصحيح هذه في Steam China باستخدام نص SteamChina - الصينية المبسطة`,
  _ = `أدخل ملاحظات برنامج التصحيح (مثل قائمة نقطية للتغييرات في النسخة التي أتحتها للتو)`,
  _ = `أدخل عنوان برنامج التصحيح (مثل "ملاحظات تحديث 2 ديسمبر")`,
  _ = `عرض الحدث المنشور`,
