  _ = `إذا كانت لعبتك تحتوي على نظام مكافحة غش في برنامج التشغيل أو على الخادم وليس في وضع kernel، فإن هذا الحقل اختياري، لكننا نعتقد عمومًا أن أي لعبة تستخدم تقنية مكافحة الغش ستستفيد من إعلام اللاعبين بذلك.`,
