  _ = `تتيح لك هذه الواجهة تقديم صورة تصف الفرق بين نسخ لعبتك (على سبيل المثال، النسخة القياسية، والنسخة الفاخرة، ونسخة لعبة العام، وغيرها). ستُجمع النسخ مع اللعبة الأساسية في الجزء العلوي من خيارات الشراء وتصنيفها من أقل سعر إلى أعلى سعر على صفحة المتجر. لمزيد من التفاصيل، يُرجى الاطلاع على <1>إدارة وثائق النسخ</1>.`,
