  _ = `عرض اللافتة الترويجية لتطبيقات في منطقة الشراء لهذه الحزمة.`,
  _ = `(عدّل قائمة اللافتات الترويجية الخاصة بهذه الحزمة لعرضها في صفحة "تحرير حزمة المتجر" أدناه.)`,
  _ = `سيؤدي هذا إلى إضافة صورة اللافتة الترويجية إلى عرض شراء الحزمة في المتجر، على غرار طريقة عرض محتويات الباقات. سيتم عرض التطبيق الأساسي أولاً، ثم بقية التطبيقات المضمّنة من الأعلى سعرًا إلى الأقل سعرًا.`,
  _ = `احذف اسم اللعبة من بداية العناصر في قائمة محتويات الحزمة.`,
  _ = `لتقليل التكرار وزيادة قابلية القراءة، احذف اسم اللعبة بالإضافة إلى المسافات وأي رموز ربط مثل النقطتين والشَرطة من بداية العناصر مثل الـDLC والموسيقى التصويرية عند عرضها ضمن قسم شراء الحزمة. على سبيل المثال، سيظهر الاسم "Half Life 2: Episode 1" باسم "Episode 1". يتم إخفاء الاسم الدقيق للعبة الأساسية فقط مع المسافات والفواصل الشائعة مثل الشَرطة والنقطتين.`,
  _ = `حفظ ونشر`,
  _ = `إلغاء`,
  _ = `فعالية التحديث الرئيسية المميزة`,
  _ = `سيتم توجيه مالكي اللعبة إلى الفعالية في مكتبتهم لتوفير السياق. نبحث عن الفعاليات المرتبطة باللعبة الأساسية.`,
  _ = `[مجهز للبدء في %1$s] اسم الفعالية: %2$s`,
  _ = `[مسودة] اسم الفعالية: %2$s`,
  _ = `[بدأت: %1$s] اسم الفعالية: %2$s`,
  _ = `لم يتم العثور على فعالية مؤهلة. يتطلب ذلك مسودة أو فعالية نُشرت حديثًا (خلال الشهر الماضي). <1>راجع لوحة تحكم الفعاليات والإعلانات</1>`,
  _ = `تم حفظ موضع شعارك. يمكنك نشر هذه التغييرات عبر إدارة صفحة المتجر.`,
  _ = `إدارة الخصومات`,
  _ = `مواعيد البيع قابلة للتغيير. يجب توخي الحذر عند الإعلان عن التواريخ، خاصة بالنسبة للفعاليات البعيدة في المستقبل.`,
  _ = `ملاحظات`,
  _ = `تذكير: لا يمكن إرسال أي خصومات خلال 30 يومًا من إصدار لعبة لأول مرة بالسعر الكامل أو من زيادة السعر بأي عملة. يرجى الاطلاع على %1$s للحصول على التفاصيل الكاملة.`,
  _ = `الوثائق`,
  _ = `تبدأ الخصومات وتنتهي عند الساعة 10 صباحًا بتوقيت المحيط الهادئ ما لم يُذكر خلاف ذلك.`,
