  _ = `استيراد/تصدير الخصومات`,
  _ = `الأدوات`,
  _ = `استيراد/تصدير ملف CSV...`,
  _ = `يمكنك أيضًا إدارة خصومات حزم ألعابك من خلال إجراء تعديلات على ملف csv. قد تجد هذا مفيدًا إذا كنت بحاجة إلى تحديث العديد من الخصومات دفعة واحدة، أو للتحقق من الاتساق عبر كتالوج كبير من الألعاب.`,
  _ = `نزّل جدول الخصومات من لوحة التحكم إلى ملف CSV. سيحتوي هذا الجدول على تغييرات لم تُحفظ بعد.`,
