  _ = `ارفع ملف CSV يحتوي على جدول خصومات مُحدّث. ستُضاف أي بيانات لا تتطابق مع الخصومات الحالية إلى لوحة التحكم كتغييرات قيد التأكيد. يمكنك معاينة التغييرات قبل الإرسال.`,
