  _ = `الاستخدام: تمثل هذه الصورة فعالية البيع الخاصة بك، ويتم استخدامها أحيانًا عندما نحتاج إلى عرض الترويج في أماكن بديلة.`,
  _ = `التصميم: يجب أن يتضمن شعار فعاليتك فوق شبكة من ألعابك الأكثر شعبية حتى يتمكن اللاعبون من رؤية بعض الألعاب التي يعرفونها.`,
