  _ = `اللافتات الترويجية البارزة (%1$s)`,
  _ = `الاستخدام: تظهر اللافتات الترويجية البارزة بالقرب من أعلى الصفحة الرئيسية في Steam ومراكز المتجر ذات الصلة للعروض الترويجية المحددة مثل عروض منتصف الأسبوع أو عروض نهاية الأسبوع.`,
  _ = `التصميم: سيتم تلقائيًا عرض قسم في أسفل اللافتة البارزة يحتوي على نص يصف نوع العرض الترويجي (مثل "عرض نهاية الأسبوع") وتواريخ انتهاء العرض الترويجي.`,
