  _ = `معاينة الرسالة التسويقية: `,
  _ = `طلب مفاتيح اختبار اللعب`,
  _ = `استخدم هذا النموذج لطلب مفاتيح Steam لحزمة اختبار اللعب. تتم مراجعة جميع طلبات مفاتيح Steam من قبل Valve لكل حالة على حدة، وعادةً خلال 48-72 ساعة.`,
  _ = `يُرجى استخدام المربع الموضح أدناه لإخبارنا أيضًا عن الغرض المقصود من رموز التفعيل هذه، حتى نتمكن من مساعدتك في التأكد من طلب الكمية المناسبة لاحتياجاتك.`,
