  _ = `إجمالي قوائم الأمنيات`,
  _ = `عدد قوائم الأمنيات الجديدة التي تلقتها لعبتك خلال الفعالية.`,
  _ = `لُعبت وأُضيفت إلى قائمة الأمنيات`,
  _ = `يشمل الألعاب التي لعبها وأضافها اللاعبون إلى قائمة أمنياتهم خلال الفعالية. هذا الرقم شامل؛ إذ يُحتسب هنا بالإضافة إلى احتسابه ضمن إجمالي اللاعبين وإجمالي قوائم الأمنيات.`,
