  _ = `لُعبت وأُضيفت إلى قائمة الأمنيات`,
  _ = `زيارات المتجر من صفحة الفعالية`,
  _ = `الزيارات إلى صفحة متجرك التي جاءت من صفحة Next Fest أثناء الفعالية. يظهر فقط للألعاب حيث يمكنك عرض حركة التسويق.`,
  _ = `زيارات المتجر في أثناء Next Fest`,
  _ = `جميع الزيارات إلى صفحة متجر الألعاب الخاصة بك أثناء الفعالية، من أي مكان على Steam أو الويب. يظهر فقط للألعاب حيث يمكنك عرض حركة التسويق.`,
  _ = `اكتشاف: لاعبون فريدون جدد`,
