  _ = `راجع الوثائق التالية جول إدارة حسابات Steamworks.`,
  _ = `Steam Next Fest`,
  _ = `للمزيد من المعلومات حول Steam Next Fest، يرجى الاطلاع على الوثائق هنا:`,
  _ = `وثائق Steam Next Fest`,
  _ = `ليس لديك أي ألعاب شاركت مؤخرًا في فعالية Next Fest.`,
