  _ = `للمطورين فقط`,
  _ = `مؤرشف`,
  _ = `يقتصر على مالكي المحتوى الإضافي المحدد فقط`,
  _ = `ستكون المجموعات المؤرشفة مرئية فقط للاعبين الذين سبق لهم فتح إنجاز من هذه المجموعات.`,
  _ = `ستكون المجموعات الخاصة بالمطورين فقط مرئية لمطوري التطبيق فقط، سواء تم إصدار التطبيق أم لا.`,
  _ = `لا يوجد صفحة متجر منشورة لـ %1$s. سيشاهد اللاعبون بدلًا من ذلك العمل الفني لـ %2$s ورابط المتجر الخاص بها.`,
  _ = `التطبيق %1$s غير مدرج كمحتوى إضافي لـ %2$s.`,
  _ = `لا يوجد إنجازات في هذه المجموعة. لن تظهر هذه المجموعة لأي أحد.`,
  _ = `هل تريد بالتأكيد حذف هذه المجموعة؟`,
  _ = `حذف`,
  _ = `يجب عليك نقل أو حذف جميع الإنجازات في هذه المجموعة قبل حذف المجموعة نفسها. يمكنك أيضًا تحديد المجموعة كـ "غير متوفرة" إذا كنت ترغب في إيقاف استخدامها دون حذف الإنجازات.`,
  _ = `إنشاء إنجاز`,
