  _ = `سيؤدي نقل الإنجازات إلى مجموعة غير منشورة إلى إخفائها عن المستخدمين الذين حصلوا عليها مسبقًا`,
  _ = `نقل`,
  _ = `قد يؤدي نقل الإنجازات من مجموعة مرئية إلى مجموعة مخفية إلى إخفائها عن المستخدمين.`,
  _ = `قد يؤدي نقل الإنجازات إلى مجموعة منشورة إلى تعطيل إكمالها بالنسبة للاعبين`,
